function getLanguage() {
    try {
        const stored = localStorage.getItem('zc_lang');
        if (stored && SUPPORTED_LANGUAGES.includes(stored)) return stored;
    } catch (e) { /* private mode / blocked storage — fall through to default */ }
    return DEFAULT_LANGUAGE;
}

function setLanguage(lang) {
    if (!SUPPORTED_LANGUAGES.includes(lang)) return;
    try { localStorage.setItem('zc_lang', lang); } catch (e) { /* non-fatal */ }
    applyI18n();
    // applyI18n() only covers static [data-i18n] elements — pages that
    // build content with t() at render time listen for this to redraw it.
    document.dispatchEvent(new Event('zc:languagechange'));
}

function t(key, params) {
    const lang = getLanguage();
    let text = (TRANSLATIONS[lang] && TRANSLATIONS[lang][key]) || TRANSLATIONS.en[key] || key;
    if (params) {
        for (const k in params) text = text.replaceAll(`{${k}}`, params[k]);
    }
    return text;
}

// Turns an API error body's `detail` (see app/errors.py) into a message in
// the current language: the translated code when there is one, the
// server's English message otherwise, plus any technical detail as-is.
function formatApiError(detail, status) {
    if (detail && typeof detail === 'object' && !Array.isArray(detail)) {
        const params = detail.params || {};
        const key = `error.${detail.code}`;
        const translated = t(key, params);
        let text = translated !== key ? translated : (detail.message || `HTTP ${status}`);
        if (params.detail) text += ` (${params.detail})`;
        return text;
    }
    if (typeof detail === 'string' && detail) return detail;
    return `HTTP ${status}`;
}

function applyI18n(root) {
    const scope = root || document;
    scope.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        const text = t(key);
        const attr = el.getAttribute('data-i18n-attr');
        if (attr) el.setAttribute(attr, text);
        else el.textContent = text;
    });
    const sel = document.getElementById('language-select');
    if (sel) sel.value = getLanguage();
    document.documentElement.lang = getLanguage();
}

document.addEventListener('DOMContentLoaded', () => {
    applyI18n();
    const sel = document.getElementById('language-select');
    if (sel) sel.addEventListener('change', (e) => setLanguage(e.target.value));
});
